<?php declare(strict_types=1);if(PHP_SAPI!=='cli'){exit(1);}$root=dirname(__DIR__);if(in_array('--demo',$argv,true)){fwrite(STDERR,"Демонстрационный режим удалён.\n");exit(1);}if(is_file($root.'/.env')){fwrite(STDERR,".env already exists; no overwrite. For a new database import database/schema.sql.\n");exit(1);}$env=file_get_contents($root.'/.env.example');$replace=['SESSION_SECRET'=>base64_encode(random_bytes(32)),'TOKEN_ENCRYPTION_KEY'=>base64_encode(random_bytes(32))];if(in_array('--provision-local',$argv,true)){$url=getenv('MYSQL_ADMIN_URL');$u=$url?parse_url($url):false;if(!$u||!in_array($u['host']??'',['127.0.0.1','localhost'],true)){throw new RuntimeException('Set a loopback MYSQL_ADMIN_URL for local provisioning');}$p=new PDO('mysql:host='.$u['host'].';port='.($u['port']??3306),rawurldecode($u['user']??''),rawurldecode($u['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);if(!str_starts_with((string)$p->query('SELECT VERSION()')->fetchColumn(),'8.0.')){throw new RuntimeException('MySQL 8.0 required');}$password=bin2hex(random_bytes(24));$user='sp_'.bin2hex(random_bytes(4));$p->exec('CREATE DATABASE IF NOT EXISTS studpulse CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci');$p->exec('CREATE USER '.$p->quote($user)."@'localhost' IDENTIFIED BY ".$p->quote($password));$p->exec('GRANT ALL PRIVILEGES ON studpulse.* TO '.$p->quote($user)."@'localhost'");$replace['DATABASE_URL']='mysql://'.$user.':'.$password.'@'.$u['host'].':'.($u['port']??3306).'/studpulse';if(($u['user']??'')==='root'&&($u['pass']??'')===''){$p->exec("ALTER USER 'root'@'localhost' IDENTIFIED BY ".$p->quote(bin2hex(random_bytes(32))));}}foreach($replace as$k=>$v){$env=preg_replace('/^'.preg_quote($k,'/').'=.*$/m',$k.'='.$v,$env);}file_put_contents($root.'/.env',$env,LOCK_EX);chmod($root.'/.env',0600);foreach(['files','mail','logs','worker']as$dir){if(!is_dir($root.'/storage/'.$dir)){mkdir($root.'/storage/'.$dir,0700,true);}}echo"Created private .env with random keys. Import database/schema.sql into the selected MySQL database.\n";